update storage.buckets set public = false, file_size_limit = 10485760, allowed_mime_types = array['image/jpeg','image/png','image/webp','application/pdf']::text[] where id = 'chat-media'; drop policy if exists "Anyone can view chat media" on storage.objects; drop policy if exists "Staff can upload chat media" on storage.objects; drop policy if exists "Staff can delete own chat media" on storage.objects;